    // species 25: C5H4O
    species[25] = -7.35423503e-01 + 3.34873827e-02 * T + 1.67738470e-06 * T2 -
                  2.96207455e-08 * T3 + 1.54431476e-11 * T4;
    // species 26: C5H5
    species[26] = -1.65017800e-02 + 3.36514760e-02 * T - 1.10541810e-07 * T2 -
                  3.67433940e-08 * T3 + 2.31411840e-11 * T4;
    // species 27: C6H5CH2
