  // reaction 193:  C6H5 + O <=> C5H5 + CO
  k_f = 100000000;
  qf[193] *= k_f;
  qr[193] *= k_f * exp(-(-g_RT[8] + g_RT[14] - g_RT[26] + g_RT_qss[8]));
  // reaction 194:  C6H5 + OH <=> C6H5O + H
  k_f = 30000000;
  qf[194] *= k_f;
  qr[194] *= k_f * exp(-(g_RT[15] - g_RT[19] - g_RT[28] + g_RT_qss[8]));
  // reaction 195:  C6H5 + HO2 <=> C6H6 + O2
  k_f = 1000000;
